questionvariables.text:
/* Generate the means and standard deviations for the two datasets.
   The second mean is shifted from the first, while its standard
   deviation is a multiple of the first. */
mean1:rand(101)+100;
aa:rand([-1,0,1]);
mean2:mean1+(rand(11)+5)*aa;
sd1:rand(5)+5;
bb:rand([1/3,1/2,1,2,3]);
sd2:sd1*bb;

/* Generate two datasets of equal size. */
ds1:rand(70)+30;
ds2:ds1;

/* Generate normally distributed observations, rounded to integers,
   and sort them for construction of the dotplots. */
dun1:makelist(round(float(quantile_normal(rand(1.0),mean1,sd1))),i,1,ds1);
dorx1:sort(dun1);
dun2:makelist(round(float(quantile_normal(rand(1.0),mean2,sd2))),i,1,ds2);
dorx2:sort(dun2);

/* Find the maximum frequency of any value in each dataset.
   These are used to determine the vertical spacing of the dotplots. */
maxfreq1:0;
k:1;
for i:2 thru ds1 do
    if dorx1[i]=dorx1[i-1]
    then (k:k+1, if maxfreq1 < k then maxfreq1:k)
    else k:1;

maxfreq2:0;
k:1;
for i:2 thru ds2 do
    if dorx2[i]=dorx2[i-1]
    then (k:k+1, if maxfreq2 < k then maxfreq2:k)
    else k:1;

/* Set common plotting limits so that both dotplots use the same scale. */
xmin:if dorx1[1]<=dorx2[1] then dorx1[1]-2 else dorx2[1]-2;
xmax:if dorx1[ds1]>=dorx2[ds2] then dorx1[ds1]+2 else dorx2[ds2]+2;
ymin:-4;
ymax:maxfreq1+maxfreq2+5;

/* Generate vertical coordinates for the first dotplot.
   It is placed above the second dotplot with sufficient separation. */
j:1;
dory1:makelist(0,i,1,ds1);
dory1[1]:1+maxfreq2+3;
for i:2 thru ds1 do
    if dorx1[i]=dorx1[i-1]
    then (j:j+1, dory1[i]:j+maxfreq2+3)
    else (j:1, dory1[i]:j+maxfreq2+3);

/* Generate vertical coordinates for the second dotplot. */
j:1;
dory2:makelist(0,i,1,ds2);
dory2[1]:1;
for i:2 thru ds2 do
    if dorx2[i]=dorx2[i-1]
    then (j:j+1, dory2[i]:j)
    else (j:1, dory2[i]:j);

/* Combine the two datasets and calculate the teacher answers. */
combined:append(dorx1,dorx2);
ta1:float(mean(combined));
ta2:float(std(combined));
